1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	import org.springframework.samples.petclinic.repository.OwnerRepository;
5	
6	/**
7	 * Derives an owner's {@code membershipTier} — the display-only rank returned on the owner DTO.
8	 *
9	 * <p>Precedence, highest first:
10	 * <ul>
11	 *   <li>{@code GOLD} — the owner belongs to a household (a non-null {@code householdId}) whose
12	 *       membership is 3 or more, counting every owner sharing that identifier. Households are stamped
13	 *       by {@link AssignHousehold} at create time, so once a household reaches three members every one
14	 *       of them reports GOLD.</li>
15	 *   <li>{@code SILVER} — the owner's name is unique ({@code namesakeCount == 0}) and an email is on
16	 *       file.</li>
17	 *   <li>{@code BRONZE} — otherwise.</li>
18	 * </ul>
19	 *
20	 * <p>The tier is computed at read time (not persisted) so a household crossing the GOLD threshold is
21	 * reflected immediately for members created before the threshold was reached.
22	 */
23	public final class MembershipTier {
24	
25	    private static final int GOLD_HOUSEHOLD_SIZE = 3;
26	
27	    private MembershipTier() {
28	    }
29	
30	    /** The full tier, applying the GOLD household rule over the base BRONZE/SILVER rules. */
31	    public static String of(Owner owner, OwnerRepository ownerRepository) {
32	        if (owner.getHouseholdId() != null && householdSize(owner, ownerRepository) >= GOLD_HOUSEHOLD_SIZE) {
33	            return "GOLD";
34	        }
35	        return baseTier(owner);
36	    }
37	
38	    /** The pre-GOLD ranking from the owner's own fields alone. */
39	    private static String baseTier(Owner owner) {
40	        boolean silver = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0
41	                && owner.getEmail() != null && !owner.getEmail().isBlank();
42	        return silver ? "SILVER" : "BRONZE";
43	    }
44	
45	    /** The number of owners sharing this owner's household identifier. */
46	    private static long householdSize(Owner owner, OwnerRepository ownerRepository) {
47	        String householdId = owner.getHouseholdId();
48	        long count = 0;
49	        for (Owner existing : ownerRepository.findAll()) {
50	            if (householdId.equals(existing.getHouseholdId())) {
51	                count++;
52	            }
53	        }
54	        return count;
55	    }
56	}
