3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	
6	/**
7	 * Assigns the owner's {@code membershipNumber}, formatted {@code <customerCode>-M<YY>} where
8	 * customerCode is the owner's already-assigned customer code and YY is the last two digits of the
9	 * registrationDate year, zero-padded (e.g. {@code SYD-SMI-0007-M26}).
10	 *
11	 * <p>Runs after {@link AssignCustomerCode} (which sets the customer code) and after
12	 * {@link BuildOwner} (which defaults the registration date), so both inputs are present.
13	 */
14	public class AssignMembershipNumber {
15	
16	    public void service(@Val Owner owner) {
17	        int yy = owner.getRegistrationDate().getYear() % 100;
18	        owner.setMembershipNumber(String.format("%s-M%02d", owner.getCustomerCode(), yy));
19	    }
20	}
