1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	
6	import net.officefloor.plugin.variable.Out;
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	
10	/**
11	 * Resolves the effective registration date and rolls it onto a business day, publishing it for
12	 * later steps. The effective date is the one supplied in the request, or the server's current date
13	 * when none was supplied. When that date falls on a weekend (Saturday or Sunday) it rolls forward to
14	 * the following Monday, so the stored {@code registrationDate} is always a business day.
15	 *
16	 * <p>Publishing the adjusted date here (before {@link CheckDailyLimit} and {@link BuildOwner}) means
17	 * every value derived from it stays consistent: the daily create-limit counts owners per adjusted
18	 * business day, and the membership number's year segment uses the adjusted year.
19	 */
20	public class ResolveRegistrationDate {
21	
22	    public void service(@Val OwnerFieldsDto request, Out<LocalDate> registrationDate) {
23	        LocalDate effective = request.getRegistrationDate();
24	        if (effective == null) {
25	            effective = LocalDate.now();
26	        }
27	        // A weekend rolls forward to the next Monday.
28	        while (effective.getDayOfWeek() == DayOfWeek.SATURDAY
29	                || effective.getDayOfWeek() == DayOfWeek.SUNDAY) {
30	            effective = effective.plusDays(1);
31	        }
32	        registrationDate.set(effective);
33	    }
34	}
