1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.beans.factory.annotation.Autowired;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
12	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
13	import org.springframework.samples.petclinic.rest.function.owner.MembershipTier;
14	
15	import java.util.Collection;
16	import java.util.List;
17	
18	/**
19	 * Maps Owner & OwnerDto using Mapstruct.
20	 *
21	 * <p>An abstract class rather than an interface so the {@code membershipTier} rule can consult the
22	 * {@link OwnerRepository}: the GOLD tier depends on how many owners share the household, which the
23	 * owner's own fields cannot tell us (see {@link MembershipTier}).
24	 */
25	@Mapper(uses = PetMapper.class)
26	public abstract class OwnerMapper {
27	
28	    @Autowired
29	    protected OwnerRepository ownerRepository;
30	
31	    @Mapping(target = "displayName",
32	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
33	    @Mapping(target = "initials",
34	        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
35	    @Mapping(target = "membershipTier",
36	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.MembershipTier.of(owner, ownerRepository))")
37	    @Mapping(target = "locality",
38	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.CityRegion.localityOf(owner.getCity()))")
39	    @Mapping(target = "bulkSignupWarning", ignore = true)
40	    public abstract OwnerDto toOwnerDto(Owner owner);
41	
42	    public abstract Owner toOwner(OwnerDto ownerDto);
43	
44	    @Mapping(target = "id", ignore = true)
45	    @Mapping(target = "pets", ignore = true)
46	    public abstract Owner toOwner(OwnerFieldsDto ownerDto);
47	
48	    public abstract List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
49	
50	    public abstract Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
51	
52	    public OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
53	        OwnerPageDto ownerPageDto = new OwnerPageDto();
54	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
55	        ownerPageDto.setPage(ownerPage.getNumber());
56	        ownerPageDto.setSize(ownerPage.getSize());
57	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
58	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
59	        return ownerPageDto;
60	    }
61	}
