1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.Map;
5	
6	/**
7	 * Fixed city-to-region lookup used to derive an owner's {@code locality}.
8	 *
9	 * <p>The table is intentionally closed: only Sydney, Melbourne and Brisbane map to a
10	 * canonical region. Any other (or missing) city derives the locality {@code "UNKNOWN"}.
11	 */
12	public final class CityRegion {
13	
14	    /** City (case-insensitive) -> canonical region. */
15	    private static final Map<String, String> CITY_REGION = Map.of(
16	        "sydney", "NSW",
17	        "melbourne", "VIC",
18	        "brisbane", "QLD");
19	
20	    /** Locality returned when the city is not in {@link #CITY_REGION}. */
21	    public static final String UNKNOWN = "UNKNOWN";
22	
23	    private CityRegion() {
24	    }
25	
26	    /** The canonical region for {@code city}, or {@code "UNKNOWN"} when it is not in the table. */
27	    public static String localityOf(String city) {
28	        if (city == null) {
29	            return UNKNOWN;
30	        }
31	        return CITY_REGION.getOrDefault(city.trim().toLowerCase(Locale.ROOT), UNKNOWN);
32	    }
33	}
